 // Final reno decisions sent to I-Niche (John) on 21 Nov. Codes are from the 13 Nov quote.
 // s: 'Go ahead', 'Changed', 'New', 'Removed', 'On hold', 'Asked', '3 Dec' or 'Not asked'.
 decisionsTitle: 'Reno decisions (21 Nov) vs the revised quote',
 decisionsNote: 'Codes are the 13 Nov quote. Each line says what the revised quote (S$19,035) did. "Fix" = ask John to change before signing.',
 decisions: [
  {t: 'A: hacking A1, A2, A4 to A9', s: 'Go ahead', n: 'In the quote. Protection S$380 did not go down although less is hacked: ask.'},
  {t: 'KS built-in wardrobe: hack away and dispose (KS, 24 Nov)', s: 'New', n: 'Was A3 in the 13 Nov quote and taken out on 21 Nov. KS now wants it removed: hack, dispose, patch and paint the wall, vinyl under where it stood. Asked John for the price on 24 Nov. KS then needs a new wardrobe (on the to-buy list).'},
  {t: 'Living mirror cabinet: take off the door and patch', s: 'Fix', n: 'Quote A3 (new): "dismantle tall mirror door cabinet" S$180. Patching and painting the wall after is not written: ask John to add it, and confirm whole cabinet or door only.'},
  {t: 'B: partition wall B1, B1a, B1b', s: 'Go ahead', n: 'Same prices. 40 kg rockwool.'},
  {t: 'B2: keep the living false ceiling, patch old downlight holes', s: 'Go ahead'},
  {t: 'B3: plywood support in the balcony for the Steigen hanger', s: 'New', n: 'Added by John, S$180. Fine (Steigen needs a solid ceiling fixing).'},
  {t: 'C1 (i) to (v): fit basins, toilets, bidet sprays, showers, accessories', s: 'Go ahead', n: 'Same S$1,030. The family buys the fittings.'},
  {t: 'D1: TV feature wall', s: 'Go ahead', n: 'Same S$840.'},
  {t: 'D2: new living mirror door', s: 'Removed'},
  {t: 'D4: L-shaped wardrobe', s: 'Removed', n: 'V Haus makes it.'},
  {t: 'D3 + D3a: platform bed and bedhead (KS bedroom)', s: 'On hold', n: 'Now optional: S$1,260 + drawers S$280 (new) + bedhead S$550. Likely drop (Dunlopillo bed).'},
  {t: 'E2 + E2a: glass sliding door at the kitchen entrance', s: 'Fix', n: 'Quote says glass BI-FOLD door, frameless 10 mm, S$1,180 (+S$150 black frame: in or extra?). We asked for SLIDING. Ask for the sliding price with black slim frame and fluted glass.'},
  {t: 'E3: shower screen, master bathroom', s: 'Go ahead', n: 'Now E4, S$890 with swing door.'},
  {t: 'Common bathroom glass on the half-height wall', s: 'Go ahead', n: 'Now E3: fixed glass panel S$380.'},
  {t: 'E4: frosted film, master bathroom', s: 'Go ahead', n: 'Now E5, S$320.'},
  {t: 'Doors: move the common bathroom door to bedroom 3', s: 'Fix', n: 'Only optional lines 3 + 4 (aluminium slide and swing door S$480 + move old door S$80), while E1 new veneer door S$580 is still in the total. Take E1 out, move 3 + 4 in.'},
  {t: 'F1: painting + Anti-Mould Ceiling White', s: 'Go ahead', n: 'F1 S$1,680, sealer S$450, Anti-Mould top-up S$300 (kitchen + 2 bathrooms; estimate was S$150, a bit high).'},
  {t: 'F2: vinyl in the 3 bedrooms', s: 'Changed', n: 'XingFloors 5 mm, about 380 sq ft at S$4.50 = S$1,710, + remove skirting S$280 + trim 3 doors S$180. Floor patching not included; thresholds not named. Parquet polish S$950 left as optional only (not needed).'},
  {t: 'F2a, F4, F6: skirting varnish, master bathroom floor polish, final cleaning', s: 'Go ahead', n: 'Now F2a, F3, F6. Same prices.'},
  {t: 'F5: half-height wall, common bathroom', s: 'Fix', n: 'Now F4, S$980 with a shampoo niche (was S$1,250 full wall). Waterproofing NOT included: ask the price.'},
  {t: 'Full regrouting of both bathrooms', s: 'New', n: 'F5: S$280 per bathroom = S$560.'},
  {t: 'G1: living room ceiling lights', s: 'Go ahead'},
  {t: 'G2 + G2a: 1 ventilation fan, common bathroom only', s: 'Fix', n: 'Priced for 1 (S$550 + S$45) but the text still says "2 bathrooms". Ask to correct the wording and give the fan brand and model.'},
  {t: 'G3 (new): move the heater switch at the kitchen entrance', s: 'New', n: 'Added by John, S$180. Likely because the new glass door covers it: ask.'},
  {t: 'G3 (ours): sockets and switches', s: '3 Dec', n: 'Quote G4: to confirm on site. Also Cat6 to KY room, WD518AN water + power, wardrobe LED point.'},
 ],
