export const toSGD=(i,rate=BUY.rate)=>i.cur==='MYR'?i.price/rate:i.price;
export const lineSGD=(i,rate=BUY.rate)=>toSGD(i,rate)*(i.qty??1);
// The family's saved choices live in the shared visit_notes table, keyed b:<item id>:tag|pick|qty.
// b:<id>:off is the old "not counted" switch: it still reads as Maybe until a tag is chosen.
export const TAGS=['before','after','maybe'];
export const TAG_NAMES={before:'Before move-in',after:'After move-in',maybe:'Maybe'};
export const optionsOf=i=>[i,...(i.alts??[])];
export function buyKeys(plan=BUY){const k=new Map();for(const t of plan.todo??[])k.set(`t:${t.id}`,{kind:'off'});for(const r of plan.rooms)for(const i of r.items){k.set(`b:${i.id}:off`,{kind:'off'});k.set(`b:${i.id}:tag`,{kind:'tag'});k.set(`b:${i.id}:qty`,{kind:'qty'});k.set(`b:${i.id}:pay`,{kind:'pay'});if(i.alts?.length)k.set(`b:${i.id}:pick`,{kind:'pick',max:i.alts.length,...(i.choose?{zero:true}:{})});}return k;}
export function validBuyValue(spec,value){if(value==='')return true;if(spec.kind==='off')return value==='1';if(spec.kind==='tag')return TAGS.includes(value);if(spec.kind==='pay')return PAYS.includes(value);if(!/^\d{1,2}$/.test(value))return false;const n=Number(value);return spec.kind==='qty'?n>=1&&n<=99:n>=(spec.zero?0:1)&&n<=spec.max;}
// Money plan: when each item is paid. b:<id>:pay = '' (auto from the buy date), now, dec, later, or i6/i12/i24 (monthly instalments).
export const PAYS=['now','dec','later','i6','i12','i24'];
export const PAY_NAMES={now:'By 30 Nov (Black Friday)',dec:'December',later:'After move-in',i6:'6-month instalments',i12:'12-month instalments',i24:'24-month instalments'};
export const autoPay=(i,tag)=>tag==='after'?'later':i.payAuto?i.payAuto:!i.date?'dec':i.date<='2026-11-30'?'now':i.date<='2026-12-31'?'dec':'later';
export function payOf(i,v={}){const c=choiceOf(i,v),saved=v[`b:${i.id}:pay`],auto=autoPay(i,c.tag),mode=PAYS.includes(saved)?saved:'';
 const m=mode||auto,months=m[0]==='i'?Number(m.slice(1)):0;return {mode,auto,use:m,months,split:!mode&&i.split?i.split:null};}
export function moneyPlan(plan=BUY,v={}){
 const b={paid:[],now:[],dec:[],later:[],inst:[]},conv=(n,cur)=>cur==='MYR'?n/plan.rate:n,S=n=>'S$'+Math.round(n).toLocaleString('en-SG'),R=n=>'RM'+Number(n).toLocaleString('en-SG',{maximumFractionDigits:2});
 // how = why the amount is what it is (quantity, RM conversion, share of a total).
 const howOf=(o,qty)=>[qty>1?`${qty} × ${o.cur==='MYR'?R(o.price):S(o.price)}`:'',o.cur==='MYR'?`${qty>1?'':R(o.price)+' '}at RM${plan.rate} = S$1`:''].filter(Boolean).join(', ');
 for(const r of plan.rooms)for(const i of r.items){if(i.ordered)continue;const c=choiceOf(i,v);if(c.off)continue;const amt=fullSGD(i,v,plan.rate),p=payOf(i,v),name=c.opt.name,how=howOf(c.opt,c.qty);
  if(i.paid){b.paid.push({id:i.id,name,amount:amt,how});continue;}
  if(p.months)b.inst.push({id:i.id,name,amount:amt,months:p.months,monthly:amt/p.months,how});
  else if(p.split)for(const [k,f,t] of p.split)b[k].push({id:i.id,name:`${name}: ${t}`,amount:amt*f,how:`${Math.round(f*100)}% of ${S(amt)}`});
  else b[p.use].push({id:i.id,name,amount:amt,how});}
 for(const x of plan.paidExtra??[])b.paid.push({name:x.name,amount:x.amount,how:x.date?`Paid ${x.date.slice(8)}/${x.date.slice(5,7)}`:''});
 for(const o of plan.orders??[]){const n=o.name.split(' (')[0],how=x=>o.cur==='MYR'?`${R(x.amount)} at RM${plan.rate} = S$1`:'';for(const x of o.paid??[])b.paid.push({name:`${n}: ${x.t}`,amount:conv(x.amount,o.cur),how:how(x)});
  for(const x of o.due??[]){const k=!x.date?'dec':x.date<='2026-11-30'?'now':x.date<='2026-12-31'?'dec':'later';b[k].push({name:`${n}: ${x.t}`,amount:conv(x.amount,o.cur),fixed:true,tbc:!x.date,how:how(x)});}}
 const sum=l=>l.reduce((s,x)=>s+x.amount,0);
 return {...b,sums:{paid:sum(b.paid),now:sum(b.now),dec:sum(b.dec),later:sum(b.later),inst:sum(b.inst),monthly:b.inst.reduce((s,x)=>s+x.monthly,0)}};
}
export function choiceOf(i,v={}){const opts=optionsOf(i),p=Number(v[`b:${i.id}:pick`]),pick=Number.isInteger(p)&&p>0&&p<opts.length?p:0,q=Number(v[`b:${i.id}:qty`]),qty=Number.isInteger(q)&&q>=1&&q<=99?q:(i.qty??1);
 const saved=v[`b:${i.id}:tag`],tag=TAGS.includes(saved)?saved:v[`b:${i.id}:off`]==='1'?'maybe':(i.tag??'before');
 return {tag,off:tag==='maybe',pick,qty,opt:opts[pick]};}
export const chosenSGD=(i,v={},rate=BUY.rate)=>{const c=choiceOf(i,v);return c.off?0:toSGD(c.opt,rate)*c.qty;};
export const fullSGD=(i,v={},rate=BUY.rate)=>{const c=choiceOf(i,v);return toSGD(c.opt,rate)*c.qty;};
// before + after = total. maybe is listed apart and not in total.
export function buyTotals(plan=BUY,v={}){
 const isEst=i=>{const c=choiceOf(i,v);return !!(c.opt.est??(c.pick===0&&i.est));};
 const rooms=plan.rooms.map(r=>{const by=t=>r.items.filter(i=>choiceOf(i,v).tag===t),sum=list=>list.reduce((s,i)=>s+fullSGD(i,v,plan.rate),0),on=r.items.filter(i=>!choiceOf(i,v).off),maybe=by('maybe');
  return {id:r.id,name:r.name,total:sum(on),before:sum(by('before')),after:sum(by('after')),est:sum(on.filter(isEst)),removed:maybe.length,offTotal:sum(maybe)};});
 const sum=k=>rooms.reduce((s,r)=>s+r[k],0);
 return {rooms,total:sum('total'),before:sum('before'),after:sum('after'),est:sum('est'),removed:sum('removed'),offTotal:sum('offTotal')};
}
export function buyCSV(plan=BUY,v={}){
 const q=x=>{let s=String(x??'');if(/^[=+\-@]/.test(s)&&!/^-?\d/.test(s))s="'"+s;return /[",\n]/.test(s)?'"'+s.replace(/"/g,'""')+'"':s;};
 const rows=[['Room','Item','Model','Qty','Unit price','Currency','Line total (S$)','Pay','Choice','Estimate?','Shop','Where','Buy date','When','Link','Note','Pay when']];
 for(const r of plan.rooms)for(const i of r.items){const c=choiceOf(i,v),o=c.opt;rows.push([r.name,o.name,o.model??'',c.qty,o.price,o.cur,fullSGD(i,v,plan.rate).toFixed(2),TAG_NAMES[c.tag],c.pick?`Option ${c.pick}`:'Recommended',(o.est??(c.pick===0&&i.est))?'Yes':'',o.shop??'',o.type??'',i.date??'',i.when??'',o.href??'',o.note??(c.pick?'':i.note??''),i.ordered?'Ordered (see Payments)':PAY_NAMES[payOf(i,v).use]]);}
 const t=buyTotals(plan,v);rows.push([]);rows.push(['Before move-in','','','','','',t.before.toFixed(2)]);rows.push(['After move-in','','','','','',t.after.toFixed(2)]);rows.push(['Total (before + after)','','','','','',t.total.toFixed(2)]);rows.push(['Maybe (not in total)','','','','','',t.offTotal.toFixed(2)]);
 return rows.map(r=>r.map(q).join(',')).join('\n')+'\n';
}
